import { tags } from "typia";

/**
 * Configuration for currency handling, exchange rates, and supported currencies
 * in the platform. This determines how prices are displayed and processed for
 * customers in different regions.
 *
 * This configuration controls the base currency for all financial transactions,
 * the set of additional currencies customers can view prices in, and the
 * exchange rate sourcing and update mechanisms. It ensures accurate pricing,
 * compliance with regional requirements, and financial consistency across all
 * customer touchpoints.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallPaymentSettingsCurrencyConfig = {
  /**
   * The primary currency code used for all financial transactions in the
   * system. This is the default currency for pricing, accounting, and
   * reporting. Must be a valid ISO 4217 currency code (e.g., USD, EUR, JPY).
   */
  baseCurrency: "USD";

  /**
   * List of additional currencies that customers can select to view product
   * prices. Products will be displayed in these currencies with exchange
   * rates applied. Must include only valid ISO 4217 currency codes.
   */
  supportedCurrencies: (
    | "EUR"
    | "GBP"
    | "CAD"
    | "AUD"
    | "JPY"
    | "CHF"
    | "SEK"
    | "NOK"
    | "DKK"
    | "MXN"
    | "BRL"
    | "INR"
    | "CNY"
    | "SGD"
    | "HKD"
  )[];

  /**
   * Specifies the data source for currency exchange rates. This affects rate
   * accuracy, update frequency, and reliability. Must be one of the supported
   * rate providers.
   */
  exchangeRateSource:
    | "fixer.io"
    | "exchangerate-api.com"
    | "currencyapi.com"
    | "internal-rate-db";

  /**
   * Frequency at which exchange rates are automatically refreshed from the
   * configured source. Must be a valid time interval to ensure rates remain
   * current.
   */
  rateUpdateInterval: "hourly" | "daily" | "weekly";

  /**
   * When enabled, allows for dynamic pricing adjustments based on currency
   * exchange rate fluctuations. When disabled, prices are fixed in local
   * currencies and do not change with exchange rate movements.
   */
  enableDynamicPricing: true;

  /**
   * Determines how currency amounts are displayed to customers. Choices
   * affect user experience and localization compliance. Must be formatted as
   * a valid display preference.
   */
  currencyDisplayFormat: "symbol-first" | "code-first" | "code-last";

  /**
   * Minimum number of decimal places to display for exchange rates in user
   * interface. Determines currency conversion precision shown to customers.
   * Must be between 4 and 8 decimal places to maintain accuracy without
   * overwhelming users.
   */
  minimumExchangeRatePrecision: number &
    tags.Type<"int32"> &
    tags.Minimum<4> &
    tags.Maximum<8>;

  /**
   * Currency to use when a customer's preferred currency is not supported or
   * when exchange rate data is unavailable. Must be a valid ISO 4217 currency
   * code and must be included in supportedCurrencies array.
   */
  fallbackCurrency: "USD";

  /**
   * Controls whether the system automatically converts product prices to the
   * customer's geolocated currency on page load. If disabled, customers must
   * manually select their preferred currency.
   */
  autoConvertToCustomerCurrency: true;

  /**
   * Defines the rounding method applied to converted prices for
   * customer-facing display. Must be a valid rounding strategy compatible
   * with each currency's smallest denomination.
   */
  currencyRoundingRule: "nearest" | "floor" | "ceiling" | "banker";
};
